	@Test
	void laterFoldFailureKeepsSuccessfulMergeAndUntouchedTailAndCleansOnce() {
		Factory factory;
		try (Fixture fixture = new Fixture()) {
			factory = fixture.factory;
			for (int i = 1; i <= 4; i++) {
				Statement statement = statement(i);
				fixture.write(sink -> sink.approve(statement));
			}
			fixture.releaseObserver();
			factory.failOn = statement(3);
			assertSame(factory.failure, assertThrows(IllegalStateException.class, fixture.branch::compressChanges));
			assertEquals(Set.of(statement(1), statement(2)), Set.copyOf(factory.models.get(0)));
			assertTrue(factory.models.get(1).closed);
			assertEquals(Set.of(statement(3)), Set.copyOf(factory.models.get(2)));
			assertEquals(Set.of(statement(4)), Set.copyOf(factory.models.get(3)));
			assertFalse(factory.models.get(2).closed);
			assertFalse(factory.models.get(3).closed);
			assertEquals(1, factory.closedCount());

			fixture.branch.compressChanges();
			assertEquals(Set.of(statement(1), statement(2), statement(3), statement(4)), fixture.statements());
			assertEquals(3, factory.closedCount());
		}
		assertEquals(4, factory.closedCount());
		assertTrue(factory.models.stream().allMatch(model -> model.closeCalls == 1));
	}

