	private static final class Factory implements ModelFactory {
		final List<TrackedModel> models = new ArrayList<>();
		final IllegalStateException failure = new IllegalStateException("Injected later-fold failure");
		Statement failOn;

		@Override
		public Model createEmptyModel() {
			TrackedModel model = new TrackedModel(this);
			models.add(model);
			return model;
		}

		long closedCount() {
			return models.stream().filter(model -> model.closed).count();
		}

		void beforeAdd(Statement statement) {
			if (statement.equals(failOn)) {
				failOn = null;
				throw failure;
			}
		}
	}

	private static final class TrackedModel extends LinkedHashModel implements AutoCloseable {
		private final Factory factory;
		boolean closed;
		int closeCalls;

		TrackedModel(Factory factory) {
			this.factory = factory;
		}

		@Override
		public boolean add(Statement statement) {
			factory.beforeAdd(statement);
			return super.add(statement);
		}

		@Override
		public boolean add(Resource subject, IRI predicate, Value object, Resource... contexts) {
			if (contexts.length == 0) {
				factory.beforeAdd(VF.createStatement(subject, predicate, object));
			} else {
				for (Resource context : contexts) {
					factory.beforeAdd(VF.createStatement(subject, predicate, object, context));
				}
			}
			return super.add(subject, predicate, object, contexts);
		}

		@Override
		public void close() {
			assertFalse(closed, "A statement model must be closed exactly once");
			closed = true;
			closeCalls++;
			clear();
		}
	}

